ValidationRule.errorConditionFormula:
AND( OR(ISBLANK(Owner:User.ContactId),
        RecordType.Name ='Application(Opt-In)'
       ),
    ISBLANK(TEXT( Offer__c )),
     OR(
         NOT(ISBLANK( Grade__c )),
         NOT(ISBLANK(  Program_Offered__c )),
         NOT(ISBLANK(Tuition_Stated_on_Offer__c ))
        )
    )
